agent.js.content:
import { cfg } from '../lib/config.js';
import { addTurn, getRecentTurns } from '../lib/memory.js';
import { aiChat } from '../lib/ai.js';
import { buildBotProfile } from '../lib/botProfile.js';

const locks = new Set();
let globalInFlight = 0;
const GLOBAL_CAP = 1;

function mentioned(ctx, text) {
  const username = ctx.me?.username || ctx.botInfo?.username || '';
  if (!username) return false;
  return text.toLowerCase().includes('@' + username.toLowerCase());
}

function stripMention(ctx, text) {
  const username = ctx.me?.username || ctx.botInfo?.username || '';
  return username ? text.replace(new RegExp('@' + username + '\\b', 'ig'), '').trim() : text.trim();
}

export function registerAgent(bot) {
  bot.on('message:text', async (ctx, next) => {
    const raw = ctx.message?.text || '';
    if (raw.startsWith('/')) return next();
    const isPrivate = ctx.chat?.type === 'private';
    const replyToBot = ctx.message?.reply_to_message?.from?.is_bot;
    if (!isPrivate && !mentioned(ctx, raw) && !replyToBot) return next();
    const text = stripMention(ctx, raw);
    if (!text) return ctx.reply('Напишіть, чим допомогти щодо МетеоUA.');
    const key = String(ctx.chat?.id || ctx.from?.id || 'unknown');
    if (locks.has(key)) return ctx.reply('Я ще працюю над вашим попереднім запитом.');
    if (globalInFlight >= GLOBAL_CAP) return ctx.reply('Зараз зайнятий. Спробуйте ще раз за хвилину.');
    locks.add(key);
    globalInFlight += 1;
    try {
      await addTurn({ mongoUri: cfg.MONGODB_URI, platform: 'telegram', userId: ctx.from?.id, chatId: ctx.chat?.id, role: 'user', text });
      const history = await getRecentTurns({ mongoUri: cfg.MONGODB_URI, platform: 'telegram', userId: ctx.from?.id, chatId: ctx.chat?.id, limit: 12 });
      const messages = [
        { role: 'system', content: buildBotProfile() },
        { role: 'system', content: 'Відповідай українською. Не вигадуй погодні факти. Якщо потрібні фактичні погодні дані, запропонуй команди /weather, /forecast або /alerts.' },
        ...history.map((m) => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: String(m.text || '').slice(0, 1500) })),
        { role: 'user', content: text.slice(0, 3000) }
      ];
      const res = await aiChat(cfg, messages, { feature: 'assistant', chatId: ctx.chat?.id, userId: ctx.from?.id });
      const reply = res.ok && res.content ? res.content : 'AI-помічник тимчасово недоступний. Для функцій бота використайте /help.';
      await addTurn({ mongoUri: cfg.MONGODB_URI, platform: 'telegram', userId: ctx.from?.id, chatId: ctx.chat?.id, role: 'assistant', text: reply });
      await ctx.reply(reply.slice(0, 3900));
    } finally {
      locks.delete(key);
      globalInFlight -= 1;
    }
  });
}

moderationFilter.js.content:
import { cfg } from '../lib/config.js';
import { addWarning, isLocked, logModerationAction } from '../services/store.js';
import { log, safeErr } from '../lib/log.js';

const buckets = new Map();
const badWords = ['лохотрон', 'шахрай', 'ідіот', 'дебіл'];
const mentionRe = /@\w+/g;
const urlRe = /(https?:\/\/|t\.me\/|www\.)/i;

export function registerModerationFilter(bot) {
  bot.on('message', async (ctx, next) => {
    const text = ctx.message?.text || ctx.message?.caption || '';
    if (!ctx.chat || ctx.chat.type === 'private' || text.startsWith('/')) return next();
    try {
      const userId = String(ctx.from?.id || 'unknown');
      const key = ctx.chat.id + ':' + userId;
      const now = Date.now();
      const rows = (buckets.get(key) || []).filter((ts) => now - ts < cfg.FLOOD_WINDOW_MS);
      rows.push(now);
      buckets.set(key, rows);
      let reason = '';
      if (rows.length > cfg.FLOOD_MAX_MESSAGES) reason = 'антифлуд';
      if (!reason && await isLocked(ctx.chat.id, 'links') && urlRe.test(text)) reason = 'посилання заблоковані';
      if (!reason && (text.match(mentionRe) || []).length >= 6) reason = 'масові згадки';
      if (!reason && badWords.some((w) => text.toLowerCase().includes(w))) reason = 'образи або підозрілий текст';
      if (!reason) return next();
      await ctx.deleteMessage().catch((err) => log.warn('moderation delete fallback', { err: safeErr(err) }));
      await addWarning({ userId, chatId: ctx.chat.id, type: 'auto', severity: 1, reason, issuedBy: 'bot' });
      await logModerationAction({ actionType: 'auto_delete_warn', targetUserId: userId, actorUserId: 'bot', chatId: String(ctx.chat.id), reason });
      return;
    } catch (err) {
      log.error('moderation filter failed', { err: safeErr(err) });
      return next();
    }
  });
}

scheduler.js.content:
import { cfg } from '../lib/config.js';
import { memoryLog, log, safeErr } from '../lib/log.js';
import { getWeather, formatForecast } from '../services/weather.js';
import { getOfficialAlerts, formatAlerts } from '../services/alerts.js';
import { claimPublication, markPublication } from '../services/store.js';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
let running = false;
let stopped = false;
let cycle = 0;

function kyivStamp() {
  return new Intl.DateTimeFormat('uk-UA', { timeZone: cfg.DEFAULT_TIMEZONE, hour: '2-digit', minute: '2-digit', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}

async function publish(bot, type, text) {
  if (!cfg.TELEGRAM_CHANNEL_ID) return;
  const key = type + ':' + kyivStamp();
  if (!(await claimPublication(key))) return;
  try {
    const sent = await bot.api.sendMessage(cfg.TELEGRAM_CHANNEL_ID, text);
    await markPublication(key, { status: 'sent', sentAt: new Date(), telegramMessageId: sent.message_id, type, targetChannelId: cfg.TELEGRAM_CHANNEL_ID });
  } catch (err) {
    await markPublication(key, { status: 'failed', error: safeErr(err), type, targetChannelId: cfg.TELEGRAM_CHANNEL_ID });
    log.error('publication failed', { err: safeErr(err) });
  }
}

async function runCycle(bot) {
  const hhmm = new Intl.DateTimeFormat('uk-UA', { timeZone: cfg.DEFAULT_TIMEZONE, hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
  const schedules = [
    ['morning', cfg.MORNING_FORECAST_TIME, 'today'],
    ['day', cfg.DAY_FORECAST_TIME, 'today'],
    ['evening', cfg.EVENING_FORECAST_TIME, 'today'],
    ['tomorrow', cfg.TOMORROW_FORECAST_TIME, 'tomorrow']
  ];
  for (const [type, time, mode] of schedules) {
    if (hhmm === time) {
      const data = await getWeather(cfg.DEFAULT_CITY);
      await publish(bot, type, formatForecast(data, mode));
    }
  }
  if (cycle % 10 === 0) {
    const alerts = await getOfficialAlerts();
    if (alerts.alerts.length) await publish(bot, 'official-alerts', formatAlerts(alerts));
  }
}

export function startScheduler(bot) {
  if (running) return;
  running = true;
  stopped = false;
  log.info('scheduler started', { enabled: cfg.AUTO_PUBLICATIONS_ENABLED, channelSet: Boolean(cfg.TELEGRAM_CHANNEL_ID) });
  (async () => {
    while (!stopped) {
      cycle += 1;
      try {
        log.info('scheduler cycle', { cycle });
        if (cfg.AUTO_PUBLICATIONS_ENABLED) await runCycle(bot);
        if (cycle % 60 === 0) memoryLog();
      } catch (err) {
        log.error('scheduler cycle failed', { err: safeErr(err) });
      }
      await sleep(60000);
    }
  })();
}

export function stopScheduler() {
  stopped = true;
  running = false;
}

index.js.content:
import 'dotenv/config';

function safeErr(err) {
  return err?.response?.data?.error?.message || err?.response?.data?.message || err?.message || String(err);
}

let shuttingDown = false;
let activeRunner = null;
let stopSchedulerFn = null;

process.on('unhandledRejection', (reason) => {
  console.error(JSON.stringify({ level: 'error', message: 'unhandledRejection', err: safeErr(reason) }));
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error(JSON.stringify({ level: 'error', message: 'uncaughtException', err: safeErr(err) }));
  process.exit(1);
});

function requestShutdown(signal) {
  console.log(JSON.stringify({ level: 'info', message: 'shutdown requested', signal }));
  shuttingDown = true;
  if (stopSchedulerFn) stopSchedulerFn();
  if (activeRunner) activeRunner.stop();
}

process.once('SIGINT', () => requestShutdown('SIGINT'));
process.once('SIGTERM', () => requestShutdown('SIGTERM'));

async function boot() {
  try {
    const { run } = await import('@grammyjs/runner');
    const { cfg } = await import('./lib/config.js');
    const { log, memoryLog } = await import('./lib/log.js');
    const { createBot } = await import('./bot.js');
    const { registerCommands } = await import('./commands/loader.js');
    const { registerModerationFilter } = await import('./features/moderationFilter.js');
    const { registerAgent } = await import('./features/agent.js');
    const { startScheduler, stopScheduler } = await import('./features/scheduler.js');

    stopSchedulerFn = stopScheduler;

    log.info('boot start', {
      'TELEGRAM_BOT_TOKEN set': Boolean(cfg.TELEGRAM_BOT_TOKEN),
      'MONGODB_URI set': Boolean(cfg.MONGODB_URI),
      'COOKMYBOTS_AI_ENDPOINT set': Boolean(cfg.COOKMYBOTS_AI_ENDPOINT),
      'COOKMYBOTS_AI_KEY set': Boolean(cfg.COOKMYBOTS_AI_KEY),
      'TELEGRAM_MOD_CHAT_ID set': Boolean(cfg.TELEGRAM_MOD_CHAT_ID),
      'TELEGRAM_OWNER_ID set': Boolean(cfg.TELEGRAM_OWNER_ID || cfg.OWNER_TELEGRAM_IDS.length),
      'DEFAULT_CITY set': Boolean(cfg.DEFAULT_CITY),
      'UKRHYDROMET_ALERTS_URL set': Boolean(cfg.UKRHYDROMET_ALERTS_URL),
      'WEATHER_NEWS_RSS_URL set': Boolean(cfg.WEATHER_NEWS_RSS_URL)
    });

    if (!cfg.TELEGRAM_BOT_TOKEN) {
      console.error('TELEGRAM_BOT_TOKEN is required. Add your BotFather token to TELEGRAM_BOT_TOKEN, then restart this single Node.js service.');
      process.exit(1);
    }

    const bot = createBot(cfg.TELEGRAM_BOT_TOKEN);
    await bot.init();
    await registerCommands(bot);
    registerModerationFilter(bot);
    registerAgent(bot);

    await bot.api.setMyCommands([
      { command: 'start', description: 'Головне меню' },
      { command: 'weather', description: 'Поточна погода' },
      { command: 'forecast', description: 'Прогноз' },
      { command: 'alerts', description: 'Попередження УкрГМЦ' },
      { command: 'news', description: 'Погодні новини' },
      { command: 'report', description: 'Повідомити про погодну подію' },
      { command: 'ticket', description: 'Створити звернення' },
      { command: 'moderation', description: 'Меню модерації' },
      { command: 'reset', description: 'Очистити памʼять AI' },
      { command: 'help', description: 'Допомога' }
    ]).catch((err) => log.warn('set commands failed', { err: safeErr(err) }));

    await bot.api.deleteWebhook({ drop_pending_updates: true });
    log.info('telegram webhook cleared', { dropPendingUpdates: true });

    startScheduler(bot);
    setInterval(memoryLog, 60000).unref();

    let delay = 2000;
    while (!shuttingDown) {
      try {
        log.info('polling start', { concurrency: 1 });
        activeRunner = run(bot, { runner: { concurrency: 1 } });
        await activeRunner.task();
        activeRunner = null;
        delay = 2000;
        if (!shuttingDown) log.warn('polling stopped unexpectedly; restarting', { backoffMs: delay });
      } catch (err) {
        activeRunner = null;
        const msg = safeErr(err);
        log.error('polling failed', { err: msg });
        if (shuttingDown) break;
        if (msg.includes('409') || msg.toLowerCase().includes('conflict') || msg.includes('429') || msg.toLowerCase().includes('timeout')) {
          log.warn('polling backoff', { backoffMs: delay });
          await new Promise((resolve) => setTimeout(resolve, delay));
          delay = Math.min(delay * 2, 20000);
          continue;
        }
        throw err;
      }
    }

    stopScheduler();
    log.info('bot stopped', {});
  } catch (err) {
    console.error(JSON.stringify({ level: 'error', message: 'boot failed', err: safeErr(err), code: err?.code || '' }));
    if (err?.code === 'ERR_MODULE_NOT_FOUND') console.error('Check ESM .js extensions and created files under src/.');
    process.exit(1);
  }
}

boot();

